text:
  "tStartMs": 2463110,
  "dDurationMs": 1502,
  "segs": [ {
    "utf8": "跟孤單的時候"
  } ]
}, {
  "tStartMs": 2464612,
  "dDurationMs": 901,
  "segs": [ {
    "utf8": "我們不會說一個人"
  } ]
}, {
  "tStartMs": 2465513,
  "dDurationMs": 1401,
  "segs": [ {
    "utf8": "他一直都是孤單的"
  } ]
}, {
  "tStartMs": 2466914,
  "dDurationMs": 984,
  "segs": [ {
    "utf8": "但每一個人都會有 "
  } ]
}, {
  "tStartMs": 2467898,
  "dDurationMs": 1919,
  "segs": [ {
    "utf8": "在不同時刻的孤單"
  } ]
}, {
  "tStartMs": 2469817,
  "dDurationMs": 2202,
  "segs": [ {
    "utf8": "那我自己都還是這樣的感覺"
  } ]
}, {
  "tStartMs": 2472019,
  "dDurationMs": 1585,
  "segs": [ {
    "utf8": "就是當我們人生進入到"
  } ]
}, {
  "tStartMs": 2473604,
  "dDurationMs": 1602,
  "segs": [ {
    "utf8": "尤其三四十歲以後"
  } ]
}, {
  "tStartMs": 2475206,
  "dDurationMs": 2402,
  "segs": [ {
    "utf8": "我們的事業可能已經先決定了"
  } ]
}, {
  "tStartMs": 2477608,
  "dDurationMs": 1552,
  "segs": [ {
    "utf8": "然後我們現在也專注在"
  } ]
}, {
  "tStartMs": 2479160,
  "dDurationMs": 1051,
  "segs": [ {
    "utf8": " 自己的事情上面"
  } ]
}, {
  "tStartMs": 2480211,
  "dDurationMs": 1801,
  "segs": [ {
    "utf8": "那我孤單感有時候都會一直跑上來"
  } ]
}, {
  "tStartMs": 2482012,
  "dDurationMs": 718,
  "segs": [ {
    "utf8": "一直跑上來 "
  } ]
}, {
  "tStartMs": 2482730,
  "dDurationMs": 1485,
  "segs": [ {
    "utf8": "我的想法就是台北"
  } ]
}, {
  "tStartMs": 2484215,
  "dDurationMs": 1301,
  "segs": [ {
    "utf8": "應該就是要讓大家"
  } ]
}, {
  "tStartMs": 2485516,
  "dDurationMs": 1401,
  "segs": [ {
    "utf8": "不會感受到孤單的城市"
  } ]
}, {
  "tStartMs": 2486917,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "這個非常重要"
  } ]
}, {
  "tStartMs": 2487918,
  "dDurationMs": 1385,
  "segs": [ {
    "utf8": "對 所以如果說是對"
  } ]
}, {
  "tStartMs": 2489303,
  "dDurationMs": 801,
  "segs": [ {
    "utf8": "這一個世代來講"
  } ]
}, {
  "tStartMs": 2490104,
  "dDurationMs": 2202,
  "segs": [ {
    "utf8": "我覺得這反而是一個重要的議題"
  } ]
}, {
  "tStartMs": 2492306,
  "dDurationMs": 2402,
  "segs": [ {
    "utf8": "然後也希望我們的提出來的政策"
  } ]
}, {
  "tStartMs": 2494708,
  "dDurationMs": 1902,
  "segs": [ {
    "utf8": "能夠更多的陪伴大家"
  } ]
}, {
  "tStartMs": 2496610,
  "dDurationMs": 1669,
  "segs": [ {
    "utf8": "我昨天在聽演唱會的時候 "
  } ]
}, {
  "tStartMs": 2498279,
  "dDurationMs": 934,
  "segs": [ {
    "utf8": "就很有感觸"
  } ]
}, {
  "tStartMs": 2499213,
  "dDurationMs": 901,
  "segs": [ {
    "utf8": "我那時候那麼有感觸"
  } ]
}, {
  "tStartMs": 2500114,
  "dDurationMs": 1201,
  "segs": [ {
    "utf8": "是因為那個主唱就說"
  } ]
}, {
  "tStartMs": 2501315,
  "dDurationMs": 784,
  "segs": [ {
    "utf8": "謝謝大家 "
  } ]
}, {
  "tStartMs": 2502099,
  "dDurationMs": 2119,
  "segs": [ {
    "utf8": "明明是中秋連假 大家還來聽"
  } ]
}, {
  "tStartMs": 2504218,
  "dDurationMs": 1585,
  "segs": [ {
    "utf8": "這明明就是要謝謝大家"
  } ]
}, {
  "tStartMs": 2505803,
  "dDurationMs": 684,
  "segs": [ {
    "utf8": "然後我就覺得說"
  } ]
}, {
  "tStartMs": 2506487,
  "dDurationMs": 2219,
  "segs": [ {
    "utf8": "沒有 是我們要很謝謝他"
  } ]
}, {
  "tStartMs": 2508706,
  "dDurationMs": 2502,
  "segs": [ {
    "utf8": "是因為音樂是一個很強烈的陪伴"
  } ]
}, {
  "tStartMs": 2511208,
  "dDurationMs": 1101,
  "segs": [ {
    "utf8": "沒錯"
  } ]
}, {
  "tStartMs": 2512309,
  "dDurationMs": 1802,
  "segs": [ {
    "utf8": "就是我們前面有提到Melody"
  } ]
}, {
  "tStartMs": 2514111,
  "dDurationMs": 1502,
  "segs": [ {
    "utf8": "就是我以前在孤單的時候"
  } ]
}, {
  "tStartMs": 2515613,
  "dDurationMs": 1401,
  "segs": [ {
    "utf8": "對我來說聽音樂是一個"
  } ]
}, {
  "tStartMs": 2517014,
  "dDurationMs": 1201,
  "segs": [ {
    "utf8": "非常好的一個陪伴"
  } ]
}, {
  "tStartMs": 2518215,
  "dDurationMs": 701,
  "segs": [ {
    "utf8": "我非常同意"
  } ]
}, {
  "tStartMs": 2518916,
  "dDurationMs": 2002,
  "segs": [ {
    "utf8": "所以我就會覺得說很謝謝他"
  } ]
}, {
  "tStartMs": 2520918,
  "dDurationMs": 2235,
  "segs": [ {
    "utf8": "在這個時候陪伴了大家"
  } ]
}, {
  "tStartMs": 2523153,
  "dDurationMs": 1402,
  "segs": [ {
    "utf8": "我就覺得說我們很希望"
  } ]
}, {
  "tStartMs": 2524555,
  "dDurationMs": 1601,
  "segs": [ {
    "utf8": "整個城市都是這樣的感覺"
  } ]
}, {
  "tStartMs": 2526156,
  "dDurationMs": 2686,
  "segs": [ {
    "utf8": "你知道我從看你過去 "
  } ]
}, {
  "tStartMs": 2528842,
  "dDurationMs": 1218,
  "segs": [ {
    "utf8": "受訪的一些影片"
  } ]
}, {
  "tStartMs": 2530060,
  "dDurationMs": 1302,
  "segs": [ {
    "utf8": "最近的一些談話"
  } ]
}, {
  "tStartMs": 2531362,
  "dDurationMs": 2302,
  "segs": [ {
    "utf8": "我一直覺得Puma老師就是一個"
  } ]
}, {
  "tStartMs": 2533664,
  "dDurationMs": 1935,
  "segs": [ {
    "utf8": "他很想去照顧所有的人 "
  } ]
}, {
  "tStartMs": 2535599,
  "dDurationMs": 2970,
  "segs": [ {
    "utf8": "不只是你的女兒"
  } ]
}, {
  "tStartMs": 2538569,
  "dDurationMs": 1785,
  "segs": [ {
    "utf8": "還有很多街友也好"
  } ]
}, {
  "tStartMs": 2540354,
  "dDurationMs": 1001,
  "segs": [ {
    "utf8": "弱勢也好"
  } ]
}, {
  "tStartMs": 2541355,
  "dDurationMs": 2202,
  "segs": [ {
    "utf8": "都是希望能夠被照顧到的"
  } ]
}, {
  "tStartMs": 2543557,
  "dDurationMs": 2002,
  "segs": [ {
    "utf8": "然後剛剛講到說音樂的陪伴"
  } ]
}, {
  "tStartMs": 2545559,
  "dDurationMs": 1085,
  "segs": [ {
    "utf8": "其實我剛剛提到說 "
  } ]
}, {
  "tStartMs": 2546644,
  "dDurationMs": 1718,
  "segs": [ {
    "utf8": "不管是我每一個年代"
  } ]
}, {
  "tStartMs": 2548362,
  "dDurationMs": 1468,
  "segs": [ {
    "utf8": "從以前最早的 "
  } ]
}, {
  "tStartMs": 2549830,
  "dDurationMs": 1835,
  "segs": [ {
    "utf8": "ウルトラマン的主題歌"
  } ]
